SELECT b.business_id, b.name, b.industry, b.config->>'tone' AS tone,
  (SELECT count(*) FROM vaibhavcapstone_products p WHERE p.business_id = b.business_id AND p.stock_qty > 0) AS live_products
FROM vaibhavcapstone_businesses b WHERE b.business_id = $1;

