const j = $input.first().json;
if (!j.business_id) return [{ json: { __status: 404, error: 'unknown business' } }];
return [{ json: {
  protocolVersion: '0.3.0',
  name: j.name + ' Sales Agent',
  description: 'Sales agent for ' + j.name + ' (' + (j.industry || 'retail') + '). Send a product enquiry as a natural-language message; a grounded, human-approved offer is returned as the task artifact. Every offer is reviewed by a human before release.',
  url: 'http://localhost:5678/webhook/a2a-rpc?business_id=' + j.business_id + '',
  preferredTransport: 'JSONRPC',
  provider: { organization: j.name, url: 'http://localhost:5678' },
  version: '1.0.0',
  capabilities: { streaming: false, pushNotifications: false, stateTransitionHistory: false },
  securitySchemes: { bearer: { type: 'http', scheme: 'bearer' } },
  security: [{ bearer: [] }],
  defaultInputModes: ['text/plain'],
  defaultOutputModes: ['application/json', 'text/plain'],
  skills: [{
    id: 'product_enquiry',
    name: 'Product enquiry',
    description: 'Ask about products, budgets, quantities and delivery. The task completes with a human-approved reply and 1-3 recommended in-stock products (' + j.live_products + ' products currently live).',
    tags: ['sales', 'retail', 'quote'],
    examples: ['We need 25 ergonomic chairs, budget 3 lakh, delivery in 4 weeks.']
  }]
} }];

const req = $input.first().json;
const auth = String((req.headers || {}).authorization || '');
const body = req.body || {};
const rpcId = body.id != null ? body.id : null;
const bid = (req.query || {}).business_id || '';
const err = (code, msg) => [{ json: { __route: 'error', __auth: auth, rpc: { jsonrpc: '2.0', id: rpcId, error: { code, message: msg } } } }];
if (body.jsonrpc !== '2.0' || !body.method) return err(-32600, 'invalid JSON-RPC 2.0 request');
if (body.method === 'message/send') {
  const parts = (((body.params || {}).message) || {}).parts || [];
  const text = parts.filter(p => p.kind === 'text' || p.type === 'text').map(p => p.text).join('\n').trim();
  if (!text) return err(-32602, 'message/send requires a text part');
  const meta = (body.params || {}).metadata || {};
  return [{ json: { __route: 'send', __auth: auth, rpc_id: rpcId, business_id: bid, text,
    remote_agent: String(meta.agent_name || (req.headers || {})['user-agent'] || 'unknown-a2a-client').slice(0, 120),
    from_email: String(meta.contact_email || 'agent@remote-a2a.invalid'),
    from_name: String(meta.contact_name || meta.agent_name || 'Remote Agent') } }];
}
if (body.method === 'tasks/get') {
  const tid = ((body.params || {}).id) || '';
  if (!tid) return err(-32602, 'tasks/get requires params.id');
  return [{ json: { __route: 'get', __auth: auth, rpc_id: rpcId, business_id: bid, task_id: tid } }];
}
return err(-32601, 'method not found: ' + body.method + ' (supported: message/send, tasks/get)');

const r = $('Route RPC').first().json;
const resp = $input.first().json;
if (!resp.ok || !resp.lead_id) return [{ json: { __fail: true, rpc: { jsonrpc: '2.0', id: r.rpc_id, error: { code: -32000, message: 'intake rejected: ' + JSON.stringify(resp.errors || resp.error || 'unknown') } } } }];
return [{ json: { __fail: false, rpc_id: r.rpc_id, business_id: r.business_id, lead_id: resp.lead_id,
  task_id: 'a2a_' + resp.lead_id.slice(5), remote_agent: r.remote_agent } }];

const r = $('Route RPC').first().json;
const row = $input.first().json;
if (!row.task_id) return [{ json: { rpc: { jsonrpc: '2.0', id: r.rpc_id, error: { code: -32004, message: 'task not found for this agent' } } } }];
const MAP = { RECEIVED:'working', CLASSIFIED:'working', EXTRACTED:'working', QUALIFIED:'working',
  RECOMMENDED:'working', DRAFTED:'working', PENDING_APPROVAL:'input-required', APPROVED:'working',
  SENT:'completed', REJECTED:'canceled', DISCARDED_SPAM:'rejected', DISCARDED_NOT_ENQUIRY:'rejected',
  NEEDS_REVIEW:'working', AWAITING_SETUP:'working', DEAD_LETTER:'failed' };
const state = MAP[row.status] || 'unknown';
const MSG = { 'input-required': 'A human reviewer at ' + row.business_name + ' is checking the proposed reply before it is released.',
  working: 'The enquiry is progressing through ' + row.business_name + "'s pipeline (stage: " + row.status + ').',
  rejected: 'This message was not accepted as a product enquiry.',
  canceled: 'The reviewer declined to send an offer for this enquiry.',
  failed: 'Processing failed; a human operator has been alerted.',
  completed: 'Offer approved and released by a human reviewer.' };
const task = { id: row.task_id, contextId: row.task_id, kind: 'task',
  status: { state, message: { role: 'agent', parts: [{ kind: 'text', text: MSG[state] || row.status }] }, timestamp: new Date().toISOString() } };
if (state === 'completed') task.artifacts = [{ artifactId: row.task_id + '-offer', name: 'approved-offer',
  parts: [ { kind: 'text', text: (row.reply_subject ? row.reply_subject + '\n\n' : '') + (row.reply_body || '') },
           { kind: 'data', data: { recommended_products: row.items || [] } } ] }];
return [{ json: { rpc: { jsonrpc: '2.0', id: r.rpc_id, result: task } } }];
